import{u as c}from"../assets/trpc.js";chrome.runtime.onInstalled.addListener(()=>{chrome.contextMenus.create({id:"save-to-bookie",title:"Save to Bookie",contexts:["page","link","selection"]})});chrome.contextMenus.onClicked.addListener(async(t,i)=>{if(t.menuItemId==="save-to-bookie"&&i){const n=t.linkUrl||t.pageUrl,a=t.selectionText||i.title||"Untitled";if(!n){chrome.notifications.create({type:"basic",iconUrl:"icons/icon48.png",title:"Save Failed",message:"Could not determine the URL to save."});return}try{const e=await c.bookmarks.create.mutate({url:n,title:a});chrome.notifications.create({type:"basic",iconUrl:e.favicon||"icons/icon48.png",title:"Bookmark Saved!",message:`Saved "${e.title}"`})}catch(e){let o="An unknown error occurred.";e?.data?.code==="UNAUTHORIZED"?o="You are not logged in. Please log in via the popup first.":e.message&&(o=e.message),chrome.notifications.create({type:"basic",iconUrl:"icons/icon48.png",title:"Save Failed",message:o})}}});
